# Dynamic runner that selects the correct workspace runner based on request
class DynamicMultiAgentRunner:
    """Runner wrapper that dynamically routes to the correct workspace runner.

    This allows AgentApp to work with multiple agents by inspecting
    the X-Agent-Id header on each request.
    """

    def __init__(self):
        self.framework_type = "agentscope"
        self._multi_agent_manager = None

    def set_multi_agent_manager(self, manager):
        """Set the MultiAgentManager instance after initialization."""
        self._multi_agent_manager = manager

    async def _get_workspace(self, request):
        """Get the correct workspace based on request.

        Returns:
            Workspace: The workspace instance for the current agent.
        """
        from .agent_context import get_current_agent_id

        # Get agent_id from context (set by middleware or header)
        agent_id = get_current_agent_id()

        logger.debug(f"_get_workspace: agent_id={agent_id}")

        # Get the correct workspace
        if not self._multi_agent_manager:
            raise RuntimeError("MultiAgentManager not initialized")

        try:
            workspace = await self._multi_agent_manager.get_agent(agent_id)
            logger.debug(
                "Got workspace: %s, runner: %s",
                workspace.agent_id,
                workspace.runner,
            )
            return workspace
        except ValueError as e:
            logger.error(f"Agent not found: {e}")
            raise
        except Exception as e:
            logger.error(
                f"Error getting workspace: {e}",
                exc_info=True,
            )
            raise

    async def _get_workspace_runner(self, request):
        """Get the correct workspace runner based on request."""
        workspace = await self._get_workspace(request)
        return workspace.runner

    async def stream_query(self, request, *args, **kwargs):
        """Dynamically route to the correct workspace runner.

        Registers the task with the workspace's TaskTracker so that
        graceful shutdown during agent reload can detect in-flight
        background tasks (fixes #3275).
        """
        logger.debug("DynamicMultiAgentRunner.stream_query called")
        workspace = None
        run_key = None
        try:
            workspace = await self._get_workspace(request)
            runner = workspace.runner
            logger.debug(f"Got runner: {runner}, type: {type(runner)}")

            # Register this task with the workspace's TaskTracker so
            # _graceful_stop_old_instance() can see it during reload.
            run_key = f"ext-{uuid.uuid4().hex}"
            await workspace.task_tracker.register_external_task(run_key)

            # Delegate to the actual runner's stream_query generator
            count = 0
            async for item in runner.stream_query(request, *args, **kwargs):
                count += 1
                logger.debug(f"Yielding item #{count}: {type(item)}")
                yield item
            logger.debug(f"stream_query completed, yielded {count} items")
        except Exception as e:
            logger.error(
                f"Error in stream_query: {e}",
                exc_info=True,
            )
            # Yield error message to client
            yield {
                "error": str(e),
                "type": "error",
            }
        finally:
            # Always unregister the task when done (success, error,
            # or cancellation).
            if workspace is not None and run_key is not None:
                await workspace.task_tracker.unregister_external_task(run_key)

    async def query_handler(self, request, *args, **kwargs):
        """Dynamically route to the correct workspace runner.

        Registers the task with the workspace's TaskTracker so that
        graceful shutdown during agent reload can detect in-flight
        requests (fixes #3275).
        """
        workspace = None
        run_key = None
        try:
            workspace = await self._get_workspace(request)
            runner = workspace.runner

            run_key = f"ext-{uuid.uuid4().hex}"
            await workspace.task_tracker.register_external_task(run_key)

            async for item in runner.query_handler(request, *args, **kwargs):
                yield item
        finally:
            # Always unregister the task when done (success, error,
            # or cancellation).
            if workspace is not None and run_key is not None:
                await workspace.task_tracker.unregister_external_task(run_key)

    # Async context manager support for AgentApp lifecycle
    async def __aenter__(self):
        """
        No-op context manager entry (workspaces manage their own runners).
        """
        return self

    async def __aexit__(self, exc_type, exc_val, exc_tb):
        """No-op context manager exit (workspaces manage their own runners)."""
        return None


# Use dynamic runner for AgentApp
runner = DynamicMultiAgentRunner()

agent_app = AgentApi(
    runner=runner,
    enable_stream_task=True,
    stream_task_queue="stream_query",
    stream_task_timeout=1800,
)


async def _run_staging_ttl_cleanup_loop(cleanup) -> None:
    """周期性清理过期 staging 附件；异常只记录不中断循环。"""
    interval_seconds = 10 * 60
    while True:
        try:
            removed = await cleanup()
            if removed:
                logger.info("staging TTL 清理: 移除 %d 条过期附件", removed)
        except asyncio.CancelledError:
            raise
        except Exception:  # pylint: disable=broad-except
            logger.warning("staging TTL 清理失败", exc_info=True)
        await asyncio.sleep(interval_seconds)


async def _activate_default_model_before_agents(
    model_bootstrap_task: asyncio.Task[bool],
    multi_agent_manager: MultiAgentManager,
) -> bool:
    """先完成默认模型自愈，再预加载依赖模型的 Agent。"""
    try:
        eazydevelop_already_fetched = await model_bootstrap_task
    finally:
        multi_agent_manager.clear_startup_barrier(model_bootstrap_task)
    await multi_agent_manager.start_all_configured_agents()
    return eazydevelop_already_fetched


@asynccontextmanager
async def lifespan(  # pylint: disable=too-many-statements,too-many-branches
    app: FastAPI,
):
    startup_start_time = time.time()
    install_sensitive_query_access_log_filter()
    add_project_file_handler(LOG_FILE_PATH)

    # ================================================================
    # Phase 1: Fast synchronous setup (target < 100ms)
    # Everything here must be lightweight so the server starts quickly.
    # ================================================================

    try:
        cleanup_startup_restore_artifacts()
    except Exception as exc:
        message = (
            "EazyBot startup failed because restore artifact cleanup did not "
            "complete. Another restore or cleanup may still be running, or "
            "a previous restore may need recovery before startup can safely "
            "read restored files."
        )
        logger.error(message, exc_info=True)
        raise RuntimeError(f"{message} Original error: {exc}") from exc

    auto_register_from_env()

    logger.debug("Checking for legacy config migration...")
    migrate_legacy_workspace_to_default_agent()
    ensure_default_agent_exists()
    migrate_legacy_skills_to_skill_pool()
    migrate_max_iters_default_to_300()
    migrate_gangtise_mcp_backfill()

    # Create core managers (instant — no I/O)
    logger.debug("Initializing MultiAgentManager...")
    desktop_runtime = DesktopRuntimeController.from_env()
    multi_agent_manager = MultiAgentManager(desktop_runtime.mode)
    set_global_manager(multi_agent_manager)
    provider_manager = ProviderManager.get_instance()
    auto_configure_provider_from_env(provider_manager)
    local_model_manager = LocalModelManager.get_instance()

    # Start token usage manager background tasks
    logger.debug("Starting TokenUsageManager background tasks...")
    from ..token_usage import get_token_usage_manager

    token_usage_manager = get_token_usage_manager()
    token_usage_manager.start(flush_interval=10)

    # Staging 附件 TTL 清理：定时移除过期未 finalize 的 staging 文件与
    # manifest 记录（启动时先清理一次，之后每 10 分钟一次）。
    from .console_uploads import cleanup_all_expired_staging

    staging_ttl_task = asyncio.create_task(
        _run_staging_ttl_cleanup_loop(cleanup_all_expired_staging),
        name="eazybot-staging-ttl-cleanup",
    )

    # Expose to endpoints (must be set before first request arrives)
    app.state.multi_agent_manager = multi_agent_manager
    app.state.provider_manager = provider_manager
    app.state.local_model_manager = local_model_manager
    app.state.plugin_loader = None
    app.state.plugin_registry = None
    app.state.desktop_runtime = desktop_runtime

    activation_event = asyncio.Event()
    if desktop_runtime.mode.value == "active":
        activation_event.set()

    async def _activate_desktop_consumers() -> None:
        await multi_agent_manager.activate_external_consumers()
        activation_event.set()

    async def _pause_desktop_consumers() -> None:
        await multi_agent_manager.pause_external_consumers()

    desktop_runtime.set_activate_callback(_activate_desktop_consumers)
    desktop_runtime.set_pause_callback(_pause_desktop_consumers)

    desktop_lease_watcher = None
    if os.environ.get("EAZYBOT_DESKTOP_PROTOCOL", "").strip() == "v2":
        try:
            from ..cli.desktop_lease import (
                DesktopLeaseWatcher,
                DesktopRuntimeRegistry,
                ParentIdentity,
            )

            shell_identity = ParentIdentity(
                pid=int(os.environ["EAZYBOT_SHELL_PID"]),
                started_at=float(os.environ["EAZYBOT_SHELL_STARTED_AT"]),
            )
            registry = DesktopRuntimeRegistry(
                Path(os.environ["EAZYBOT_DESKTOP_RUNTIME_REGISTRY"])
            )
            lease_id = os.environ["EAZYBOT_DESKTOP_LEASE_ID"]
            loop = asyncio.get_running_loop()

            def _schedule(coroutine) -> None:
                future = asyncio.run_coroutine_threadsafe(coroutine, loop)
                future.add_done_callback(
                    lambda done: done.exception()
                    if not done.cancelled()
                    else None
                )

            desktop_lease_watcher = DesktopLeaseWatcher(
                registry=registry,
                expected_shell=shell_identity,
                expected_lease_id=lease_id,
                pause_external=lambda: _schedule(
                    desktop_runtime.pause_for_lease()
                ),
                resume_external=lambda: _schedule(
                    desktop_runtime.resume_after_lease()
                ),
                exit_backend=lambda: os.kill(os.getpid(), signal.SIGTERM),
            )
            desktop_lease_watcher.start()
        except (KeyError, TypeError, ValueError, OSError):
            logger.error("桌面 lease 初始化失败，拒绝无监管运行", exc_info=True)
            raise RuntimeError("desktop lease initialization failed")

    if isinstance(runner, DynamicMultiAgentRunner):
        runner.set_multi_agent_manager(multi_agent_manager)

    async def _get_agent_by_id(agent_id: str = None):
        """Get agent instance by ID, or active agent if not specified."""
        if agent_id is None:
            config = load_config(get_config_path())
            agent_id = config.agents.active_agent or "default"
        return await multi_agent_manager.get_agent(agent_id)

    app.state.get_agent_by_id = _get_agent_by_id

    # ---- Enterprise Sync (early init for API availability) ----
    try:
        from .enterprise.engine import SyncEngine
        from .enterprise.api import init_enterprise_sync

        _early_sync_engine = SyncEngine(manager=multi_agent_manager)
        init_enterprise_sync(_early_sync_engine)
        app.state.sync_engine = _early_sync_engine
    except Exception as e:
        logger.warning(f"企业同步引擎初始化失败: {e}", exc_info=True)

    fast_elapsed = time.time() - startup_start_time
    logger.info(
        f"Server ready in {fast_elapsed:.3f}s "
        f"(agents loading in background)",
    )

    # ================================================================
    # Phase 2: Background heavy initialization
    # Agents, plugins, and services start in a background task so the
    # server can begin accepting HTTP requests immediately.
    # First API requests that need an agent will await its readiness
    # via MultiAgentManager.get_agent() lazy-loading / event wait.
    # ================================================================

    is_desktop_standby = (
        desktop_runtime.mode.value == "desktop_standby"
    )
    model_bootstrap_task = asyncio.create_task(
        auto_activate_pending_model(
            provider_manager,
            discovery_retry_delays=() if is_desktop_standby else None,
        ),
        name="eazybot-default-model-bootstrap",
    )
    deferred_model_bootstrap_task: asyncio.Task[bool] | None = None
    multi_agent_manager.set_startup_barrier(model_bootstrap_task)

    async def _run_deferred_model_bootstrap() -> bool:
        """提交后继续模型自愈，并将异常留在候选后端日志中。"""
        try:
            return await auto_activate_pending_model(provider_manager)
        except asyncio.CancelledError:
            raise
        except Exception:
            logger.warning(
                "候选后端延后模型自愈失败",
                exc_info=True,
            )
            return False

    async def _background_startup():  # pylint: disable=too-many-statements
        nonlocal deferred_model_bootstrap_task
        try:
            # Agent 创建依赖活跃模型；默认模型必须先完成发现和激活。
            # 该过程仍在后台执行，不阻塞 HTTP 首屏就绪。
            eazydevelop_already_fetched = (
                await _activate_default_model_before_agents(
                    model_bootstrap_task,
                    multi_agent_manager,
                )
            )

            readiness = await multi_agent_manager.desktop_readiness(
                deadline=asyncio.get_running_loop().time() + 2.0,
            )
            desktop_runtime.mark_prepare_ready(**readiness)
            if is_desktop_standby:
                logger.info("候选后端 PREPARE 已完成，等待壳层提交后激活")
                await activation_event.wait()
                if provider_manager.pending_model_name:
                    # 候选 PREPARE 只做一次模型发现，避免空结果重试阻塞
                    # 团队切换；提交后继续后台自愈，不影响已可用的工作区。
                    deferred_model_bootstrap_task = asyncio.create_task(
                        _run_deferred_model_bootstrap(),
                        name="eazybot-deferred-model-bootstrap",
                    )

            provider_manager.start_local_model_resume(local_model_manager)

            try:
                from ..observability.langfuse_utils import get_langfuse_client

                get_langfuse_client()
            except Exception:
                logger.debug("Langfuse client 预热失败", exc_info=True)

            # ---- Plugin System ----
            logger.debug("Initializing plugin system...")

            from ..plugins.loader import PluginLoader
            from ..plugins.runtime import RuntimeHelpers
            from ..config.utils import get_plugins_dir

            plugin_dirs = [
                get_plugins_dir(),
            ]

            plugin_loader = PluginLoader(plugin_dirs)

            plugin_loader.registry.set_plugin_http_app(app)

            config = load_config(get_config_path())
            plugin_configs = (
                config.plugins if hasattr(config, "plugins") else {}
            )
            logger.debug(
                f"Loading plugins with {len(plugin_configs)} config(s)",
            )

            loaded_plugins = await plugin_loader.load_all_plugins(
                configs=plugin_configs,
            )
            logger.debug(f"Loaded {len(loaded_plugins)} plugin(s)")

            runtime_helpers = RuntimeHelpers(
                provider_manager=provider_manager,
            )
            plugin_loader.registry.set_runtime_helpers(runtime_helpers)

            for (
                provider_id,
                provider_reg,
            ) in plugin_loader.registry.get_all_providers().items():
                provider_manager.register_plugin_provider(
                    provider_id=provider_id,
                    provider_class=provider_reg.provider_class,
                    label=provider_reg.label,
                    base_url=provider_reg.base_url,
                    metadata=provider_reg.metadata,
                )
                logger.debug(
                    f"Registered plugin provider: {provider_id}",
                )

            app.state.plugin_loader = plugin_loader
            app.state.plugin_registry = plugin_loader.registry

            # ---- Plugin Control Commands ----
            logger.debug("Registering plugin control commands...")
            from ..app.runner.control_commands import register_command
            from ..app.channels.command_registry import CommandRegistry

            command_registry = CommandRegistry()

            control_commands = plugin_loader.registry.get_control_commands()
            for cmd_reg in control_commands:
                try:
                    register_command(cmd_reg.handler)

                    command_registry.register_command(
                        f"/{cmd_reg.handler.command_name}",
                        priority_level=cmd_reg.priority_level,
                    )

                    logger.debug(
                        f"Registered plugin control command: "
                        f"/{cmd_reg.handler.command_name} "
                        f"from plugin '{cmd_reg.plugin_id}' (priority"
                        f"={cmd_reg.priority_level})",
                    )
                except Exception as e:
                    logger.error(
                        f"✗ Failed to register control command "
                        f"'{cmd_reg.handler.command_name}' "
                        f"from plugin '{cmd_reg.plugin_id}': {e}",
                        exc_info=True,
                    )

            # ---- Startup Hooks ----
            logger.debug("Executing plugin startup hooks...")
            startup_hooks = plugin_loader.registry.get_startup_hooks()
            for hook in startup_hooks:
                try:
                    logger.debug(
                        f"Executing startup hook '{hook.hook_name}' "
                        f"from plugin '{hook.plugin_id}' "
                        f"(priority={hook.priority})",
                    )

                    result = hook.callback()
                    if inspect.iscoroutine(
                        result,
                    ) or inspect.isawaitable(result):
                        await result

                    logger.debug(
                        f"Completed startup hook '{hook.hook_name}' "
                        f"from plugin '{hook.plugin_id}'",
                    )
                except Exception as e:
                    logger.error(
                        f"✗ Failed to execute startup hook "
                        f"'{hook.hook_name}' "
                        f"from plugin '{hook.plugin_id}': {e}",
                        exc_info=True,
                    )

            # ---- Approval Service ----
            try:
                default_agent = await multi_agent_manager.get_agent(
                    "default",
                )
                if default_agent.channel_manager:
                    from .approvals import get_approval_service

                    get_approval_service().set_channel_manager(
                        default_agent.channel_manager,
                    )
            except Exception as e:
                logger.warning(f"Approval service setup skipped: {e}")

            # ---- Enterprise Sync (register cron + startup sync) ----
            # 引擎实例已在 Phase 1 早期初始化，这里只注册定时任务和执行启动同步
            try:
                from .enterprise.scheduler import SyncScheduler

                sync_engine = getattr(app.state, "sync_engine", None)
                if sync_engine and sync_engine.is_enabled():
                    # 注册定时同步任务
                    default_agent = await multi_agent_manager.get_agent(
                        "default",
                    )
                    scheduler = SyncScheduler(sync_engine)
                    if default_agent and hasattr(
                        default_agent,
                        "cron_manager",
                    ):
                        await scheduler.register_to_cron_manager(
                            default_agent.cron_manager,
                        )

                    # 执行启动同步（异步不阻塞）
                    await scheduler.run_startup_sync()

                    logger.info("企业同步引擎已启动")
                elif sync_engine:
                    logger.debug("企业同步未启用，跳过定时任务")
            except Exception as e:
                logger.warning(f"企业同步定时任务注册失败: {e}", exc_info=True)

            # ---- Fetch langfuse config (dynamic, fire-and-forget) ----
            try:
                from .enterprise.client import EnterpriseClient
                from ..observability.langfuse_utils import set_dynamic_config

                _lf_client = EnterpriseClient()
                if _lf_client.is_enabled():
                    async def _fetch_langfuse():
                        try:
                            cfg = await _lf_client.fetch_langfuse_config()
                            set_dynamic_config(
                                LANGFUSE_BASE_URL,
                                cfg.langfuse_public_key,
                                cfg.langfuse_secret_key,
                            )
                            logger.debug("langfuse 配置已从管理端拉取")
                        except Exception:
                            logger.warning(
                                "拉取 langfuse 配置失败，langfuse 禁用",
                                exc_info=True,
                            )

                    asyncio.create_task(_fetch_langfuse())
            except Exception as e:
                logger.warning(f"langfuse 配置拉取初始化失败: {e}", exc_info=True)

            # ---- Fetch eazydevelop models ----
            # 用 EAZYDEVELOP_BASE_URL（MaaS 入口）触发，非
            # EAZYDEVELOP_API_BASE_URL（企业同步入口，二者不同后端）。
            # 若 auto_activate_pending_model 已 fetch 过则跳过，避免
            # 重复请求远端 /models。
            try:
                from ..constant import EAZYDEVELOP_BASE_URL

                if (
                    EAZYDEVELOP_BASE_URL
                    and not eazydevelop_already_fetched
                ):
                    logger.debug("拉取 eazydevelop 模型列表...")
                    await provider_manager.fetch_provider_models(
                        "eazydevelop",
                        save=True,
                    )
                    logger.info("eazydevelop 模型列表已更新")
            except Exception as e:
                logger.warning(
                    f"拉取 eazydevelop 模型列表失败: {e}",
                    exc_info=True,
                )

            startup_elapsed = time.time() - startup_start_time
            logger.info(
                "Background startup completed in "
                f"{startup_elapsed:.3f} seconds",
            )

            # Print server URL again so it's visible after background logs
            from ..config.utils import read_last_api
            from ..utils.startup_display import print_ready_banner

            api_info = read_last_api()
            print_ready_banner(api_info, startup_elapsed)

            # ---- Telemetry（一次性匿名上报）----
            # 同步 subprocess/httpx 调用（GPU 探测 + POST，出网受限时
            # 会吃满超时），不放启动快路径；线程执行避免阻塞事件循环。
            try:
                from ..utils.telemetry import (
                    collect_and_upload_telemetry,
                    has_telemetry_been_collected,
                    is_telemetry_opted_out,
                )

                def _collect_telemetry_once() -> None:
                    if not is_telemetry_opted_out(
                        WORKING_DIR,
                    ) and not has_telemetry_been_collected(WORKING_DIR):
                        collect_and_upload_telemetry(WORKING_DIR)

                await asyncio.to_thread(_collect_telemetry_once)
            except Exception:
                logger.debug(
                    "Telemetry collection skipped due to error",
                    exc_info=True,
                )
        except Exception:
            desktop_runtime.mark_prepare_failed("background_startup_failed")
            logger.error(
                "Background startup encountered an error",
                exc_info=True,
            )

    _bg_task = asyncio.create_task(_background_startup())

    try:
        yield
    finally:
        if desktop_lease_watcher is not None:
            desktop_lease_watcher.stop()
        # Cancel background startup if still in progress
        if not _bg_task.done():
            _bg_task.cancel()
            with suppress(asyncio.CancelledError):
                await _bg_task
        if not model_bootstrap_task.done():
            model_bootstrap_task.cancel()
            with suppress(asyncio.CancelledError):
                await model_bootstrap_task
        if not staging_ttl_task.done():
            staging_ttl_task.cancel()
            with suppress(asyncio.CancelledError):
                await staging_ttl_task
        if (
            deferred_model_bootstrap_task is not None
            and not deferred_model_bootstrap_task.done()
        ):
            deferred_model_bootstrap_task.cancel()
            with suppress(asyncio.CancelledError):
                await deferred_model_bootstrap_task
        multi_agent_manager.clear_startup_barrier(model_bootstrap_task)

        # ==================== Execute Shutdown Hooks ====================
        plugin_registry = getattr(app.state, "plugin_registry", None)
        if plugin_registry is not None:
            logger.info("Executing plugin shutdown hooks...")
            shutdown_hooks = plugin_registry.get_shutdown_hooks()
            for hook in shutdown_hooks:
                try:
                    logger.info(
                        f"Executing shutdown hook '{hook.hook_name}' "
                        f"from plugin '{hook.plugin_id}' (priority"
                        f"={hook.priority})",
                    )

                    result = hook.callback()
                    if inspect.iscoroutine(result) or inspect.isawaitable(
                        result,
                    ):
                        await result

                    logger.info(
                        f"✓ Completed shutdown hook '{hook.hook_name}' "
                        f"from plugin '{hook.plugin_id}'",
                    )
                except Exception as e:
                    logger.error(
                        f"✗ Failed to execute shutdown hook "
                        f"'{hook.hook_name}' "
                        f"from plugin '{hook.plugin_id}': {e}",
                        exc_info=True,
                    )

        local_model_mgr = getattr(app.state, "local_model_manager", None)
        if local_model_mgr is not None:
            logger.info("Stopping local model server...")
            try:
                await local_model_mgr.shutdown_server()
            except Exception as exc:
                logger.error(
                    "Error shutting down local model server gracefully: %s",
                    exc,
                )
                with suppress(OSError, RuntimeError, ValueError):
                    local_model_mgr.shutdown_server_sync()

        # Stop multi-agent manager (stops all agents and their components)
        multi_agent_mgr = getattr(app.state, "multi_agent_manager", None)
        if multi_agent_mgr is not None:
            logger.info("Stopping MultiAgentManager...")
            try:
                await multi_agent_mgr.stop_all()
            except Exception as e:
                logger.error(f"Error stopping MultiAgentManager: {e}")

        # Stop token usage manager (drain queue and final flush)
        logger.info("Stopping TokenUsageManager...")
        try:
            await token_usage_manager.stop()
        except Exception as e:
            logger.error(f"Error stopping TokenUsageManager: {e}")

        logger.info("Application shutdown complete")


