_CONSOLE_STATIC_ENV = "EAZYBOT_CONSOLE_STATIC_DIR"


def _resolve_console_static_dir() -> str:
    from ..constant import EnvVarLoader

    static_dir = EnvVarLoader.get_str(_CONSOLE_STATIC_ENV)
    if static_dir:
        return static_dir
    # Shipped dist lives in the package as static data
    pkg_dir = Path(__file__).resolve().parent.parent
    candidate = pkg_dir / "console"
    if candidate.is_dir() and (candidate / "index.html").exists():
        return str(candidate)

    # Fallback to repo data
    repo_dir = pkg_dir.parent.parent
    candidate = repo_dir / "console" / "dist"
    if candidate.is_dir() and (candidate / "index.html").exists():
        return str(candidate)

    # Fallback to cwd data
    cwd = Path(os.getcwd())
    for subdir in ("console/dist", "console_dist"):
        candidate = cwd / subdir
        if candidate.is_dir() and (candidate / "index.html").exists():
            return str(candidate)

    fallback = cwd / "console" / "dist"
    logger.warning(
        f"Console static directory not found. Falling back to '{fallback}'.",
    )
    return str(fallback)


_CONSOLE_STATIC_DIR = _resolve_console_static_dir()
_CONSOLE_INDEX = (
    Path(_CONSOLE_STATIC_DIR) / "index.html" if _CONSOLE_STATIC_DIR else None
)
logger.info(f"STATIC_DIR: {_CONSOLE_STATIC_DIR}")


# 运行时品牌预设：与 console/src/config/brands.data.ts 对齐。
# 仅当显式注入 EAZYBOT_APP_NAME（桌面壳 shell-ui-launch / 打包客户端）时才覆盖
# 编译期 VITE_BRAND；未注入（纯 web 部署）时回退 None，保持构建产物品牌不变。
_CONSOLE_BRAND_PRESETS = {
    "eazybot": {"id": "eazybot", "name": "EazyBot", "favicon": "/eazybot.svg"},
    "finbot": {"id": "finbot", "name": "FinBot", "favicon": "/finbot.svg"},
}


def _console_runtime_brand() -> dict | None:
    """按显式注入的 EAZYBOT_APP_NAME 返回控制台品牌预设；未注入返回 None。"""
    key = (os.environ.get("EAZYBOT_APP_NAME") or "").strip().lower()
    if not key:
        return None
    return _CONSOLE_BRAND_PRESETS.get(key)


def _render_console_index_html() -> str:
    """读取 console index.html，按运行时品牌注入 ``window.__EB_BRAND__``
    并覆盖 favicon/title（与 vite inject-brand 构建期行为对齐）。

    未显式注入品牌时原样返回（编译期 VITE_BRAND 仍是权威）。
    """
    if not _CONSOLE_INDEX or not _CONSOLE_INDEX.exists():
        raise HTTPException(status_code=404, detail="Not Found")
    html = _CONSOLE_INDEX.read_text(encoding="utf-8")
    brand = _console_runtime_brand()
    if brand is None:
        return html
    inject = (
        f'<script>window.__EB_BRAND__="{brand["id"]}";</script>'
    )
    # 注入到 <head> 最前，先于任何 bundle JS，确保 brand.ts 读到运行时值
    html = html.replace("</head>", f"  {inject}\n  </head>", 1)
    html = re.sub(
        r"<title>.*?</title>",
        f'<title>{brand["name"]} Console</title>',
        html,
        count=1,
    )
    html = re.sub(
        r'(<link\s+rel="icon"[^>]*href=")[^"]*(")',
        rf'\g<1>{brand["favicon"]}\g<2>',
        html,
        count=1,
    )
    return html


def _serve_console_index():
    if not _CONSOLE_INDEX or not _CONSOLE_INDEX.exists():
        raise HTTPException(status_code=404, detail="Not Found")
    if _console_runtime_brand() is None:
        # 未注入运行时品牌：走 FileResponse，保留编译期品牌产物不变
        return FileResponse(
            _CONSOLE_INDEX,
            headers=CONSOLE_INDEX_CACHE_HEADERS,
        )
    return HTMLResponse(
        _render_console_index_html(),
        headers=CONSOLE_INDEX_CACHE_HEADERS,
    )


def _serve_console_public_file(static_file: Path) -> FileResponse:
    if static_file.name.lower() == "index.html":
        return _serve_console_index()
    return FileResponse(
        static_file,
        headers={"Cache-Control": "public, max-age=86400"},
    )


