@app.get("/api/version")
def get_version(response: Response):
    """返回本地版本及当前桌面平台的最新安装包信息。"""
    response.headers["Cache-Control"] = "no-store"
    version = EAZYBOT_VERSION
    desktop_platform = detect_desktop_platform()
    try:
        release = fetch_latest_release()
        latest_version = (
            (release.client_version or release.version)
            if desktop_platform
            else release.version
        )
        # 只信任对外口径（client_version）作为更新判据；运营后台未填
        # client_version 时 latest 会回落到内部版本号（如 2.2.18），
        # 对外版本（1.0.7）比较会造成误报，此时视为无更新。
        # 弹更新前提：运营已提供当前平台的可下载安装包。
        # download_url 为空（未配置/该平台未发布）时一律不提示，
        # 避免内部版本号（如 2.2.18）与对外版本（1.0.7）比较造成误弹。
        _pkg_url = release.download_url_for(desktop_platform)
        has_update = (
            bool(_pkg_url)
            and bool(release.client_version)
            and has_version_update(latest_version, version)
        )
        download_url = release.download_url_for(desktop_platform)
    except VersionCheckError as exc:
        logger.warning("检查桌面客户端版本失败：%s", exc)
        return {
            "version": version,
            "latest": None,
            "has_update": False,
            "download_url": None,
            "platform": desktop_platform,
            "check_status": "error",
        }
    return {
        "version": version,
        "latest": latest_version,
        "has_update": has_update,
        "download_url": download_url,
        "platform": desktop_platform,
        "check_status": "ok",
    }


